from pathlib import Path
import json, argparse
parser=argparse.ArgumentParser(description="Build the three function-first profile entries")
parser.add_argument("--check",action="store_true")
args=parser.parse_args()
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'data/scene-stage.json').read_text(encoding='utf-8'))
copy={
'de':dict(intro='Ich bin **Juri**. Ich baue Werkzeuge, mit denen sich Zustände verändern, Abläufe beobachten und Ideen weiterentwickeln lassen.',tag='Idee öffnen. Etwas verändern. Ergebnis ansehen. Dahinter liegt der Code.',hero='Eine Anwendung: Raum und Bewegung',scarlet='Mit Zuständen, Zeit und Varianten arbeiten',endeck='Bild und Raum unterscheiden',code='Code dieser Entwicklungsfassung',tryit='Selbst ausprobieren',scope='Die Aufnahme zeigt die Entwicklungsfassung; veröffentlichte Download-Pakete haben ihren eigenen Versionsstand.',map='Was ich praktisch einbringe',maptext='C++-Spielzustände, Browseroberflächen, lokale Python-Werkzeuge, Gegenproben und reproduzierbare Builds. Die Schnittstellenkarte führt von diesen Fähigkeiten direkt zu Funktionen, Tests und Quellrevisionen.',maplink='Technik im Zusammenhang',work='Alle öffentlichen Projekte',collab='Zusammenarbeit',offer='Ich entwickle interaktive Prototypen, technische Erklärungen und lokale Werkzeuge. Für eine Zusammenarbeit vereinbaren wir ein konkretes Ziel, den Umfang und nachvollziehbare Abnahmekriterien.',credit='Projektleitung, Richtung und Auswahl: Juri / HALVETH. Entwicklung mit KI-Unterstützung. Die Aufnahmen zeigen tatsächliche native Anwendungen und Browserzustände.',sources='Herkunft und Verarbeitung der Aufnahmen',portfolio='Portfolio öffnen',evidence='Drei nachvollziehbare Fallstudien'),
'en':dict(intro='I’m **Juri**. I build tools to change states, observe sequences and develop ideas further.',tag='Open an idea. Change something. See the result. The code is behind it.',hero='One application: space and movement',scarlet='Work with states, time and variants',endeck='Distinguish image and space',code='Source for this development version',tryit='Try it yourself',scope='The capture shows development work; published download packages have their own versioned state.',map='What I contribute in practice',maptext='C++ game state, browser interfaces, local Python tools, counterexamples and reproducible builds. The interface map connects those skills directly to functions, tests and source revisions.',maplink='Connected engineering examples',work='All public projects',collab='Collaborate',offer='I develop interactive prototypes, technical explanations and local tools. A collaboration starts with a specific goal, an agreed scope and inspectable acceptance criteria.',credit='Project lead, direction and curation: Juri / HALVETH. AI-assisted development. Captures show actual native applications and browser states.',sources='Capture provenance and processing',portfolio='Open the portfolio',evidence='Three reproducible case studies'),
'ru':dict(intro='Я **Juri**. Я создаю инструменты для изменения состояний, наблюдения последовательностей и развития идей.',tag='Откройте идею. Измените что-нибудь. Посмотрите результат. За ним стоит код.',hero='Одно из применений: пространство и движение',scarlet='Работа с состояниями, временем и вариантами',endeck='Различать изображение и пространство',code='Исходники этой версии в разработке',tryit='Попробовать самому',scope='Снимок показывает работу в разработке; выпущенные пакеты имеют собственные версии.',map='Мой практический вклад',maptext='Состояния игры C++, браузерные интерфейсы, локальные инструменты Python, контрпримеры и воспроизводимые сборки. Карта интерфейсов ведёт от этих навыков к функциям, тестам и версиям кода.',maplink='Технические примеры во взаимосвязи',work='Все публичные проекты',collab='Сотрудничество',offer='Я создаю интерактивные прототипы, технические объяснения и локальные инструменты. Для совместной работы согласуем конкретную цель, объём и проверяемые критерии приёмки.',credit='Руководство, направление и подбор: Juri / HALVETH. Разработка с помощью ИИ. Снимки показывают реальные нативные приложения и состояния браузера.',sources='Происхождение и обработка снимков',portfolio='Открыть портфолио',evidence='Три воспроизводимых примера')}
for lang,t in copy.items():
    prefix='' if lang=='de' else lang+'/'
    mapname={'de':'TECHNICAL-MAP.md','en':'TECHNICAL-MAP.en.md','ru':'TECHNICAL-MAP.ru.md'}[lang]
    lines=['[Deutsch](README.md) · [English](README.en.md) · [Русский](README.ru.md)','','# Juri','',t['intro'],'','**'+t['tag']+'**','',f"[**{t['portfolio']} ↗**](https://juri-halveth.github.io/{prefix}) · [{t['evidence']}](https://juri-halveth.github.io/{prefix}belege/)",'']
    by_id={s['id']:s for s in data['scenes']}
    for scene_id in data['presentationOrder']:
        s=by_id[scene_id]
        href=s['href']+('?lang='+lang if scene_id=='scarlet' and lang!='de' else '')
        heading={'astralis':t['hero'],'scarlet':t['scarlet'],'endeck':t['endeck']}[scene_id]
        lines.extend(['## '+heading,'',f"[![{s['alt'][lang]}]({s['image'].lstrip('/')})]({href})",'', '**'+s['title'][lang]+'**','',s['purpose'][lang]+' '+s['use'][lang],'',f"[{t['code'] if scene_id=='astralis' else t['tryit']} ↗]({href})",''])
        lines.extend([s['scope'][lang],''])
        if scene_id=='astralis':lines.extend([t['scope'],''])
    lines.extend(['## '+t['map'],'',t['maptext'],'',f"[**{t['maplink']}**]({mapname}) · [{t['work']}](https://juri-halveth.github.io/{prefix}arbeiten/#repositories)",'','## '+t['collab'],'',t['offer'],'','**[security@halveth.de](mailto:security@halveth.de)**','','---','',t['credit'],'',f"[{t['sources']}](ASSET-NOTICES.md) · [HALVETH](https://juri-halveth.github.io/{prefix})",''])
    target=ROOT/('README.md' if lang=='de' else f'README.{lang}.md')
    expected='\n'.join(lines).encode('utf-8')
    if args.check:
        if not target.is_file() or target.read_bytes()!=expected: raise SystemExit('Stale scene profile: '+target.name)
    else: target.write_bytes(expected)
print('Three function-first profile entries checked.' if args.check else 'Three function-first profile entries generated.')
